import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'data'
def load(x):return json.loads((p/(x+'.json')).read_text())
def save(x,d):(p/(x+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2))
# В каждой строке текст описания и цели переписаны из отдельной страницы, а неопознанные награды оставлены файлами.
rows=[
(826,'skazka','Здравствуйте, дети. Сегодня я расскажу вам сказку об Алмазной девочке.','Приготовь черники с косточкой — 30; собери урожай вишни — 50; сделай в Вожде железные сердца — 15.','Пиктограмма shkatulka.jpg, без подписи и количества.'),
(827,'almaznaja_devochka','Жила-была Алмазная девочка.','Найди на складе Шкатулку и поставь её — 1; сделай в Шкатулке первый этаж Песочной башни — 1; обменяй Песочную коллекцию для строительства башни — 10.','5 Mramor.png + 5 chernij_mramor.png + 5 belyj-mramor.png; вероятно обычный, чёрный и белый мрамор, пиктограммы не подписаны.'),
(828,'tvjordost','Алмазная девочка была очень твёрдой, потому что алмазы и должны быть очень твёрдыми.','Накопай у друзей кувалды — 25; посади лук — 100; используй свои золотые лопаты — 100.','По 2 пиктограммы Kolpak.jpg, Metla.jpg и Tikva.jpg; подписи отсутствуют.'),
(829,'luk','Но в остальном Алмазная девочка была самой обычной девочкой.','Сделай в Шкатулке второй этаж Песочной башни — 1; продай лук — 120; удобри свои фруктовые деревья — 50.','По 10 пиктограмм pljush.jpg, svet.jpg, teplo.jpg; предположительно плюш, свет и тепло, нужна проверка.'),
(830,'zhizn_devochki','И жизнь Алмазной девочки ничем особенным не отличалась от Жизни остальных камней в природе.','Выруби до основания камни — 15; сделай в Пирамиде из камней блоки — 15; сделай в Мельнице из камней цемент — 20.','50 Udobrenija_na_30.jpg + 40 Udobrenija_na_50.jpg + 30 Mgnovennye_udobrenija.jpg; названия по файлам, визуально не сверены.'),
(831,'zolotaja_pyl','А Жизнь… слабых она крошила в пыль, а твёрдых обтачивала, пока они не становились одинаково круглыми и гладкими.','Повара приготовят Золотой пыли — 20; найди любые предметы Очень страшной коллекции — 25; сделай в Шкатулке третий этаж Песочной Башни — 1.','1 Zombaksy.jpg и 100000 gold.jpg; вероятно зомбакс и монеты, подписи отсутствуют.'),
(832,'odinakovye','И все вокруг становились круглыми и гладкими. И ничто их больше не трогало и не коробило.','Открой мешки своих кладоискателей — 15; подари друзьям Изумруд с сообщением «Я не такой!» — 5; собери и обменяй коллекцию Цветов — 15.','По 1 пиктограмме polarniy_nosok.jpg и nosok_izobiliya.jpg, имена требуют сверки.'),
(833,'ostavatsja_soboj','Алмазную девочку Жизнь тоже била и бросала в стороны, но она по-прежнему оставалась собой. Хотя ей было очень больно и обидно, почему она не как все камни.','Удобри фруктовые деревья друзей — 50; сделай в Шкатулке четвёртый этаж Песочной башни — 1; открой чемоданы туристов — 15.','15 Sol-.jpg + 10 Jodirovannaja_sol-.jpg; вероятно соль и йодированная соль, подписи отсутствуют.'),
(834,'vstrecha_s_chelovekom','Но однажды Алмазная девочка встретила человека, который ранил её сильнее, чем когда-либо Жизнь ранила. Так сильно, что эта рана осталась навсегда сверкающей гранью на её алмазном теле.','Продай ножи для бумаги — 25; приготовь Чертовщины — 25; продай Слёзы зомби — 15.','Неподписанная пиктограмма umnoe.jpg; количество не указано.'),
(835,'rana','И от этой раны Алмазная девочка стала такой острой, что все другие Камни стали опасаться и сторониться её.','Приготовь шоколад — 15; сделай в Шкатулке пятый этаж Песочной башни — 1; найди любые предметы Секретной коллекции — 25.','Неподписанная пиктограмма Bochka_povara.jpg; количество не указано.'),
(836,'ostrye_grani','Но как бы Алмазная девочка не пыталась уберечься от новых ран, Жизнь неумолимо приводила людей, которые только ранили её, оставляя новые острые грани на теле.','Закопай друзей, одетых в Дракона — 15; сделай в Шкатулке шестой этаж Песочной башни — 1; найди любые предметы коллекции Анти-зомби — 25.','250000 gold.jpg + 500 skills.jpg + 3 Zombaksy.jpg; вероятно монеты, опыт и зомбаксы, подписи отсутствуют.'),
(837,'chjornaja_shkatulka','И когда на теле больше не осталось места для новых ран, Алмазная девочка стала такой острой и опасной, что ей пришлось поселиться в чёрной бархатной шкатулке и прятаться подальше от людей.','Надень картонную коробку — 1; посети друзей — 100.','По 15 пиктограмм Zolian.png, Winograd_02.png, rambutan.jpg; точное содержание не подписано.'),
(838,'zamochnaja_skvazhina','И все только приходили и заглядывали в шкатулку через замочную скважину, пытаясь разглядеть Алмазную девочку.','Получи лампочки за Президентскую коллекцию — 10; посади Светляков — 100; накопай у друзей любые очки — 10.','Неподписанная пиктограмма Rozovii_buket.jpg, количество не указано.'),
(839,'v_temnote','Но в шкатулке было так темно, а замочная скважина была такой маленькой, что можно было разглядеть только её маленькие ладошки, коленки и локоны волос.','Сделай в Этаже №6 седьмой этаж Песочной башни — 1; освободи Алмазную девочку — 1; достань со склада Алмазную девочку — 1.','3 Zombaksy.jpg + 25 Palochka_vyruchalochka.jpg; вероятно зомбаксы и палочки-выручалочки, подписи отсутствуют.'),
(840,'eshhjo_odin_nekonec','Но все сказки должны заканчиваться хорошо и эта сказка об Алмазной девочке тоже должна закончиться хорошо. И если в ней всё ещё плохо, то значит это ещё «Неконец».','Собери и обменяй Японскую коллекцию — 10; Школьную коллекцию — 10; Песочную коллекцию — 10.','Неподписанная пиктограмма Urozhajnaja_korzina.jpg, количество не указано.')]
q=load('quests'); found=[]
for num,path,story,goals,reward in rows:
 e=next((x for x in q if any(r.get('original_id')=='zombia-quest-'+str(num) for r in x.get('prior_records',[]))),None)
 if e is None:print('MISSING',num);continue
 u=f'https://zombi.at.ua/board/menju/zadanija/{path}/21-1-0-{num}';r={'original_id':f'zombia-quest-detail-{num}','original_category':'Квесты: Алмазная девочка','version':'браузерная версия ВКонтакте; редакция неизвестна','date':'22.06.2013 — публикация, дата редакции неизвестна','fields':{'Линейка':'Алмазная девочка; позиция '+str(num-825)+' из 15 в списке источника. Последовательность в каталоге, обязательность разблокировки не проверена.','Описание квеста — полный текст страницы':story,'Цели':goals,'Награда — исходные обозначения':reward,'Диалоги NPC':'Отдельного диалога NPC на странице нет; описание не следует считать полным игровым диалогом.'},'confidence':'Прочитана отдельная фанатская страница; подписи наград отсутствуют. Названия по файлам — лишь предположения.'}
 e.setdefault('prior_records',[]);e['prior_records']=[x for x in e['prior_records'] if x.get('original_id')!=r['original_id']]+[r]
 existing=next((x for x in e['sources'] if x['url']==u),None)
 if existing:existing['label']='ZOMBIA: прочитана отдельная страница квеста'
 else:e['sources'].append({'url':u,'label':'ZOMBIA: прочитана отдельная страница квеста'})
 found.append(e)
for i,e in enumerate(found):
 for neighbor,rel in ((found[i-1] if i else None,'предыдущее в списке линейки'),(found[i+1] if i+1<len(found) else None,'следующее в списке линейки')):
  if neighbor and not any(l.get('category')=='quests' and l.get('slug')==neighbor['slug'] and l.get('relation')==rel for l in e.setdefault('links',[])):e['links'].append({'category':'quests','slug':neighbor['slug'],'name':neighbor['name'],'relation':rel})
save('quests',q)
def enrich(cat,name,url,id,fields,dt,ver='браузерная социальная версия; сеть не указана'):
 d=load(cat);e=next((x for x in d if x['name'].lower()==name.lower()),None)
 if not e:print('NOT FOUND',name);return
 e.setdefault('prior_records',[]);e['prior_records']=[r for r in e['prior_records'] if r.get('original_id')!=id]+[{'original_id':id,'original_category':'Прочитанная отдельная страница','version':ver,'date':dt,'fields':fields,'confidence':'Исторический фанатский источник. Возможна зависимость от других сайтов; дата редакции может отличаться от даты публикации.'}]
 if not any(x['url']==url for x in e['sources']):e['sources'].append({'url':url,'label':'Прочитанная отдельная страница'})
 save(cat,d)
